SELECT COUNT(*) AS "count_result" FROM triples t0, triples t1, triples t2, triples t3 WHERE t0.p = 'http://purl.org/dc/terms/Location' AND struct_pack(kind := 0::UTINYINT, value := t1.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) = struct_pack(kind := 0::UTINYINT, value := t0.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) AND t1.p = 'http://schema.org/nationality' AND t1.o = struct_pack(kind := 0::UTINYINT, value := 'http://db.uwaterloo.ca/~galuc/wsdbm/Country14', datatype := NULL::VARCHAR, lang := NULL::VARCHAR) AND struct_pack(kind := 0::UTINYINT, value := t2.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) = struct_pack(kind := 0::UTINYINT, value := t0.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) AND t2.p = 'http://db.uwaterloo.ca/~galuc/wsdbm/gender' AND struct_pack(kind := 0::UTINYINT, value := t3.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) = struct_pack(kind := 0::UTINYINT, value := t0.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) AND t3.p = 'http://www.w3.org/1999/02/22-rdf-syntax-ns#type' AND t3.o = struct_pack(kind := 0::UTINYINT, value := 'http://db.uwaterloo.ca/~galuc/wsdbm/Role2', datatype := NULL::VARCHAR, lang := NULL::VARCHAR)